.cards-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 16px;
    padding: 10px;
}

.card-wrap {
    perspective: 900px;
    height: 220px;
}

.card-wrap.hidden {
    display: none;
}

.card-inner {
    width: 100%;
    height: 100%;
    position: relative;
    transform-style: preserve-3d;
    transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
}
.card-wrap:hover .card-inner {
    transform: rotateY(180deg);
}

.card-face {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: 12px;
    border: 0.5px solid #FAF2E9;
    background: #E8E5E2;
    padding: 1.25rem;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;

      /* =============================================
         BACKGROUND IMAGE — edit per card
         Replace 'none' with url('your-image.jpg')
         The overlay keeps text readable.
         ============================================= */
    background-image: none;
    background-size: cover;
    background-position: center;
}

    /* Semi-transparent overlay so text stays readable over images.
       Increase the alpha (last value) to darken more, e.g. rgba(245,243,235,0.88) */
.card-face::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 12px;
    background: rgba(245, 243, 235, 0.82);
    z-index: 0;
}

 /* Push all card content above the overlay */
.card-face > * {
    position: relative;
    z-index: 1;
}


.card-back {
    transform: rotateY(180deg);
}

